import { useEffect, useRef, useState } from 'react';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/integrations/supabase/client';

type ParticipantSchool = { organization_id: string; name: string; role: 'student' | 'instructor' };
type ParticipantRequest = { abortSignal(signal: AbortSignal): PromiseLike<{ data: unknown; error: unknown }> };
// Existing RPC, shared Auth/proxy client; the generated Database types predate this module.
const participantRpc = supabase.rpc.bind(supabase) as unknown as (name: 'driving_my_schools') => ParticipantRequest;
function isParticipantSchool(value: unknown): value is ParticipantSchool {
  if (!value || typeof value !== 'object') return false;
  const row = value as Record<string, unknown>;
  return typeof row.organization_id === 'string' && row.organization_id.length > 0
    && typeof row.name === 'string' && (row.role === 'student' || row.role === 'instructor');
}

/** Visibility only; the existing chooser and workspace recheck all server permissions. */
export function useDrivingSchoolParticipantEntry(
  organizationId: string | null, subjectUserId: string | null, enabled = true,
) {
  const { user, loading: authLoading, authError } = useAuth();
  const userId = user?.id ?? null;
  const ready = enabled && !!organizationId && !!subjectUserId && !!userId
    && subjectUserId === userId && !authLoading && !authError;
  const key = JSON.stringify([userId, subjectUserId, organizationId, ready]);
  const scope = useRef({ key, generation: 0 });
  // Close a previous account/organization/preview scope before passive effects run.
  if (scope.current.key !== key) scope.current = { key, generation: scope.current.generation + 1 };
  const generation = scope.current.generation;
  const [result, setResult] = useState<{ key: string; generation: number; allowed: boolean } | null>(null);

  useEffect(() => {
    if (!ready || !organizationId) return;
    let active = true;
    let request = 0;
    let inFlight = false;
    let controller: AbortController | null = null;
    let timeout: ReturnType<typeof window.setTimeout> | null = null;
    const current = () => active && scope.current.key === key && scope.current.generation === generation;
    const check = async () => {
      if (!current() || inFlight) return;
      inFlight = true;
      const version = ++request;
      const read = new AbortController();
      controller = read;
      // Abort the physical fetch; do not race a timeout against an abandoned network request.
      const timer = window.setTimeout(() => read.abort(), 12000);
      timeout = timer;
      setResult({ key, generation, allowed: false });
      try {
        const { data: schools, error } = await participantRpc('driving_my_schools').abortSignal(read.signal);
        if (!current() || version !== request || read.signal.aborted) return;
        if (error) throw error;
        const allowed = Array.isArray(schools) && schools.every(isParticipantSchool)
          && schools.some(school => school.organization_id === organizationId);
        setResult({ key, generation, allowed });
      } catch {
        if (current() && version === request) setResult({ key, generation, allowed: false });
      } finally {
        window.clearTimeout(timer);
        if (timeout === timer) timeout = null;
        if (controller === read) controller = null;
        inFlight = false;
      }
    };
    const onVisible = () => { if (document.visibilityState === 'visible') void check(); };
    void check();
    window.addEventListener('focus', onVisible);
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      active = false; request++;
      controller?.abort();
      if (timeout !== null) window.clearTimeout(timeout);
      window.removeEventListener('focus', onVisible);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [key, generation, ready, organizationId]);

  return ready && result?.key === key && result?.generation === generation && result?.allowed === true;
}

import { User, LogOut, Sparkles, HelpCircle, Car } from "lucide-react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { SigmaLogo } from "@/components/ui/SigmaLogo";
import { Button } from "@/components/ui/button";
import { useNavigate } from "react-router-dom";
import { AccountSettingsMenuItem } from "@/components/account/AccountSettingsLink";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { RadioPlayerButton } from "@/components/radio/RadioPlayerButton";
import { AnnouncementsBell } from "@/components/shared/AnnouncementsBell";
import { StudentNotifications } from "@/components/student/StudentNotifications";
import { useAuth } from "@/hooks/useAuth";
import { useTheme } from "next-themes";

interface StudentHeaderProps {
  fullName: string | null;
  orgName: string | null;
  logoUrl?: string;
  onLogout: () => void;
  setTheme: (t: string) => void;
  pendingCount: number;
  /** Human-readable list of pending actions, used in the badge tooltip. */
  pendingReasons?: string[];
  isVideoIdentified: boolean;
  showAchievements: boolean;
  showRadio?: boolean;
  showAnnouncements?: boolean;
  showDrivingSchool?: boolean;

  onShowVideoId: () => void;
  onShowConsent: () => void;
  onShowDocs: () => void;
  onShowAchievements: () => void;
  onProfileClick?: () => void;
}

export function StudentHeader({
  fullName, orgName, logoUrl, onLogout, setTheme,
  pendingCount, pendingReasons, isVideoIdentified, showAchievements, showRadio = false, showAnnouncements = false,
  onShowVideoId, onShowConsent, onShowDocs, onShowAchievements,
  onProfileClick, showDrivingSchool = false,
}: StudentHeaderProps) {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { theme: currentTheme, setTheme: setAppTheme } = useTheme();
  const toggleTheme = () => setAppTheme(currentTheme === "dark" ? "light" : "dark");
  const initials = fullName
    ? fullName.split(" ").slice(0, 2).map(n => n[0]).join("").toUpperCase()
    : "У";

  const goToProfile = () => {
    if (onProfileClick && pendingCount === 0) {
      onProfileClick();
      return;
    }
    if (pendingCount > 0) {
      navigate("/student/profile?section=documents");
    } else if (onProfileClick) {
      onProfileClick();
    } else {
      navigate("/student/profile");
    }
  };

  const reasonsTooltip = pendingCount > 0
    ? (pendingReasons && pendingReasons.length > 0
        ? `${pendingCount} ${pendingCount === 1 ? "действие требует" : "действия требуют"} внимания: ${pendingReasons.join(", ")}`
        : "Требуются документы")
    : null;

  return (
    <header className="h-16 bg-card border-b border-border flex items-center justify-between px-6 shrink-0">
      <div className="flex items-center gap-3">
        {logoUrl ? (
          <Tooltip>
            <TooltipTrigger asChild>
              <button onClick={toggleTheme} className="hover:opacity-80 transition-opacity">
                <img src={logoUrl} alt="Logo" className="h-8 object-contain" />
              </button>
            </TooltipTrigger>
            <TooltipContent>Сменить тему</TooltipContent>
          </Tooltip>
        ) : (
          <Tooltip>
            <TooltipTrigger asChild>
              <button onClick={toggleTheme} className="hover:opacity-80 transition-opacity">
                <SigmaLogo size="sm" />
              </button>
            </TooltipTrigger>
            <TooltipContent>Сменить тему</TooltipContent>
          </Tooltip>
        )}
        {orgName && <span className="text-sm font-medium text-muted-foreground hidden sm:block">{orgName}</span>}
      </div>

      <div className="flex items-center gap-3">
        {/* Radio */}
        {showRadio && <RadioPlayerButton />}


        {/* Новости платформы — скрыто по умолчанию */}
        {showAnnouncements && <AnnouncementsBell />}


        {/* Personal notifications */}
        {user?.id && <StudentNotifications userId={user.id} />}

        {/* Profile dropdown */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button className="flex items-center gap-3 hover:bg-secondary rounded-lg px-3 py-2 transition-colors relative">
              <Avatar className="w-10 h-10">
                <AvatarFallback className="bg-primary/10 text-primary text-sm font-semibold">{initials}</AvatarFallback>
              </Avatar>
              {pendingCount > 0 && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span
                      role="button"
                      tabIndex={0}
                      aria-label={reasonsTooltip || "Требуются документы"}
                      onClick={(e) => { e.stopPropagation(); navigate("/student/profile?section=documents"); }}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" || e.key === " ") {
                          e.preventDefault();
                          e.stopPropagation();
                          navigate("/student/profile?section=documents");
                        }
                      }}
                      className="absolute top-0 left-7 w-5 h-5 rounded-full bg-destructive text-destructive-foreground text-[10px] flex items-center justify-center font-bold cursor-pointer hover:scale-110 transition-transform"
                    >
                      {pendingCount}
                    </span>
                  </TooltipTrigger>
                  <TooltipContent className="max-w-xs">{reasonsTooltip}</TooltipContent>
                </Tooltip>
              )}
              <span className="text-base font-medium hidden sm:block">{fullName || "Ученик"}</span>
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-56">
            <div className="px-3 py-2">
              <p className="text-sm font-medium">{fullName || "Ученик"}</p>
              <p className="text-xs text-muted-foreground">Слушатель</p>
            </div>
            <DropdownMenuSeparator />

            <DropdownMenuItem onClick={goToProfile}>
              <User className="w-4 h-4 mr-2" />
              Мой профиль
              {pendingCount > 0 && (
                <span className="ml-auto w-5 h-5 rounded-full bg-amber-500 text-white text-[10px] flex items-center justify-center font-bold">
                  {pendingCount}
                </span>
              )}
            </DropdownMenuItem>

            {showDrivingSchool && (
              <DropdownMenuItem onClick={() => navigate("/driving-school")}>
                <Car className="w-4 h-4 mr-2" />
                Автошкола
              </DropdownMenuItem>
            )}

            <AccountSettingsMenuItem />
            <DropdownMenuItem onClick={() => navigate("/student/whats-new")}>
              <Sparkles className="w-4 h-4 mr-2" />
              Что нового?
            </DropdownMenuItem>

            <DropdownMenuItem onClick={() => navigate("/help")}>
              <HelpCircle className="w-4 h-4 mr-2" />
              Помощь
            </DropdownMenuItem>

            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={onLogout} className="text-destructive">
              <LogOut className="w-4 h-4 mr-2" />
              Выйти
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </header>
  );
}

