// T-Bank SDK loader
let tbankSdkPromise: Promise<void> | null = null;
function loadTBankSdk(): Promise<void> {
  if (tbankSdkPromise) return tbankSdkPromise;
  tbankSdkPromise = new Promise((resolve, reject) => {
    if ((window as any).pay) { resolve(); return; }
    const script = document.createElement("script");
    script.src = "https://pay.tbank.ru/sdk/3.0/payment.js";
    script.onload = () => resolve();
    script.onerror = () => reject(new Error("Failed to load T-Bank SDK"));
    document.head.appendChild(script);
  });
  return tbankSdkPromise;
}

function CatalogContent({
  catalogCourses, categories, handleCourseClick,
  enrolledCourses, isVideoIdentified, totalProgress, totalTimeSpent, totalCompletedLessons, formatTime,
  user, contentTab, isAdminView,
}: any) {
  const [confirmCourse, setConfirmCourse] = useState<any>(null);
  const [enrollCourse, setEnrollCourse] = useState<any>(null);
  const [sendingCourseId, setSendingCourseId] = useState<string | null>(null);
  const [enrollingCourseId, setEnrollingCourseId] = useState<string | null>(null);
  const [paymentMode, setPaymentMode] = useState<"redirect" | "widget">("redirect");

  useEffect(() => {
    if (!user?.id) return;
    supabase
      .from("profiles")
      .select("organization_id")
      .eq("user_id", user.id)
      .maybeSingle()
      .then(({ data }) => {
        if (!data?.organization_id) return;
        supabase
          .from("organization_payment_settings")
          .select("payment_mode" as any)
          .eq("organization_id", data.organization_id)
          .maybeSingle()
          .then(({ data: paymentData }) => {
            if (paymentData) setPaymentMode((paymentData as any).payment_mode || "redirect");
          });
      });
  }, [user?.id]);

  const handleBuy = (courseId: string) => {
    const course = catalogCourses.find((c: any) => c.id === courseId);
    if (course) setConfirmCourse(course);
  };

  const handleEnroll = (courseId: string) => {
    const course = catalogCourses.find((c: any) => c.id === courseId);
    if (course) setEnrollCourse(course);
  };

  const handlePayment = async (course: any) => {
    setSendingCourseId(course.id);
    try {
      const { data, error } = await supabase.functions.invoke("tbank-init", {
        body: { course_id: course.id, user_id: user?.id, email: user?.email },
      });
      if (error || !data?.url) throw new Error(data?.error || "Ошибка инициализации оплаты");

      if (paymentMode === "widget" && data.paymentId) {
        try {
          await loadTBankSdk();
          const pay = (window as any).pay;
          if (pay) {
            pay({
              paymentId: data.paymentId,
              onSuccess: () => { toast.success("Оплата прошла успешно!"); setSendingCourseId(null); setConfirmCourse(null); },
              onClose: () => setSendingCourseId(null),
              onFail: () => { toast.error("Оплата не прошла"); setSendingCourseId(null); },
            });
            return;
          }
        } catch { console.warn("T-Bank SDK unavailable, falling back to redirect"); }
      }
      window.location.href = data.url;
    } catch (err: any) {
      console.error("Payment error:", err);
      toast.error(err.message || "Ошибка при создании платежа");
      setSendingCourseId(null);
    }
  };

  const handleEnrollRequest = async (course: any) => {
    if (!user?.id) return;
    setEnrollingCourseId(course.id);
    try {
      const { data: existingRequest } = await supabase
        .from("enrollment_requests")
        .select("id")
        .eq("user_id", user.id)
        .eq("course_id", course.id)
        .eq("status", "pending")
        .maybeSingle();

      if (existingRequest) {
        toast.info("Вы уже отправляли заявку на этот курс");
        setEnrollCourse(null);
        return;
      }

      const { error: requestError } = await supabase.from("enrollment_requests").insert({
        user_id: user.id,
        course_id: course.id,
        status: "pending"
      } as any);
      if (requestError) throw requestError;

      await supabase.functions.invoke("notify-enrollment-request", {
        body: { course_id: course.id },
      });

      toast.success("Заявка отправлена!");
      setEnrollCourse(null);
    } catch (err: any) {
      console.error("Enrollment request error:", err);
      toast.error(err.message || "Ошибка при отправке заявки");
    } finally {
      setEnrollingCourseId(null);
    }
  };

  return (
    <div className="space-y-4 md:space-y-6">
      {contentTab === "courses" && (
        <CourseCatalog
          courses={catalogCourses}
          categories={categories}
          onCourseClick={(id: string, enrolled: boolean) => handleCourseClick(id, enrolled)}
          enrolledCourses={enrolledCourses}
          isVideoIdentified={isVideoIdentified}
          totalProgress={totalProgress}
          totalTimeSpent={totalTimeSpent}
          totalCompletedLessons={totalCompletedLessons}
          formatTime={formatTime}
          onBuy={handleBuy}
          onEnroll={handleEnroll}
          isAdminView={isAdminView}
        />
      )}
      <AlertDialog open={!!confirmCourse} onOpenChange={(open) => !open && setConfirmCourse(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Оплата курса</AlertDialogTitle>
            <AlertDialogDescription>
              Вы будете перенаправлены на страницу оплаты курса
              «{confirmCourse?.title}» ({confirmCourse ? Number(confirmCourse.price).toLocaleString("ru-RU") : 0} ₽).
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Отмена</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => confirmCourse && handlePayment(confirmCourse)}
              disabled={sendingCourseId === confirmCourse?.id}
            >
              <CreditCard className="w-4 h-4 mr-2" />
              Перейти к оплате
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={!!enrollCourse} onOpenChange={(open) => !open && setEnrollCourse(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Заявка на запись</AlertDialogTitle>
            <AlertDialogDescription>
              Ваша заявка на курс «{enrollCourse?.title}» будет отправлена в учебный центр.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Отмена</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => enrollCourse && handleEnrollRequest(enrollCourse)}
              disabled={enrollingCourseId === enrollCourse?.id}
            >
              <ClipboardCheck className="w-4 h-4 mr-2" />
              Отправить заявку
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default function StudentDashboard() {
  return <CourseReviewDashboardGate><LearnerDashboard /></CourseReviewDashboardGate>;
}

function LearnerDashboard() {
  const isNativeLearner = Capacitor.isNativePlatform();
  const { userRole } = useAuth();
  const isMobile = useIsMobile();

  const isAdminViewFromStorage = (() => {
    try { return !!localStorage.getItem('adminViewAsStudent'); } catch { return false; }
  })();
  const isDemoStudent = (() => {
    try { return !!localStorage.getItem('demoStudentReturn'); } catch { return false; }
  })();
  const isPreviewFromStorage = false;

  const {
    user, navigate, theme, setTheme,
    activeTab, setActiveTab: setActiveTabRaw, messages, inputValue, setInputValue, isAiLoading, handleSendMessage,
    courses, catalogCourses, categories, profile, branding, dashboardSettings, loading, loadError, offlineCopy,
    totalTimeSpent, totalCompletedLessons, totalProgress, firstName, formatTime,
    isPreviewMode, showVideoIdentification, setShowVideoIdentification,
    showConsentForm, setShowConsentForm, showDocumentsUpload, setShowDocumentsUpload,
    showAchievements, setShowAchievements, mobileMenuOpen, setMobileMenuOpen,
    documentsProgress, isVideoIdentified, setIsVideoIdentified, showOnboarding, handleOnboardingClose,
    handleLogout, handleRefresh, pullToRefreshRef, pullDistance, isRefreshing, canRefresh, orgPlan,
    isAdminView, adminViewStudentName } = useStudentDashboard();

  // When viewing a student from admin/org, prefer the target student's id everywhere
  // so that documents, consents and uploads are read for that user (not the staff member).
  const targetStudentUserId = (() => {
    try {
      const raw = localStorage.getItem('adminViewAsStudent');
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      return parsed?.userId || null;
    } catch { return null; }
  })();
  const effectiveStudentId = (isAdminView && targetStudentUserId) ? targetStudentUserId : user?.id;
  const effectiveStudentName = profile?.full_name || (isAdminView ? adminViewStudentName : null) || "Ученик";
  const showDrivingSchool = useDrivingSchoolParticipantEntry(
    profile?.organization_id ?? null, user?.id ?? null,
    !loading && !loadError && !offlineCopy && !isAdminView && !isPreviewMode && !isDemoStudent
      && !isAdminViewFromStorage && !isPreviewFromStorage && effectiveStudentId === user?.id,
  );

  const setActiveTab = (tab: StudentTab) => setActiveTabRaw(tab as any);
  const currentTab: StudentTab = (activeTab === "store" || activeTab === "library" ? "catalog" : activeTab) as StudentTab;

  // Apply org's default visual theme if student hasn't picked their own.
  // Personal choice in localStorage always wins.
  useEffect(() => {
    const orgTheme = dashboardSettings.studentTheme;
    if (!orgTheme) return;
    const personal = getStoredThemeId();
    if (personal) return;
    storeThemeId(orgTheme);
    window.dispatchEvent(new CustomEvent("visual-theme-change", { detail: orgTheme }));
  }, [dashboardSettings.studentTheme]);

  // When student clears their personal theme, fall back to org theme on next load
  useEffect(() => {
    const handler = (e: Event) => {
      const detail = (e as CustomEvent).detail;
      if (detail === null && dashboardSettings.studentTheme) {
        storeThemeId(dashboardSettings.studentTheme);
        window.dispatchEvent(new CustomEvent("visual-theme-change", { detail: dashboardSettings.studentTheme }));
      }
    };
    window.addEventListener("visual-theme-change", handler);
    return () => window.removeEventListener("visual-theme-change", handler);
  }, [dashboardSettings.studentTheme]);

  const docsPending = documentsProgress.total - documentsProgress.completed;
  const [inboxPending, setInboxPending] = useState(0);
  useEffect(() => {
    if (!user?.id) return;
    let cancelled = false;
    const load = async () => {
      const { count } = await supabase
        .from("document_signatures")
        .select("id", { count: "exact", head: true })
        .eq("recipient_user_id", user.id)
        .in("status", ["sent", "viewed", "in_review"])
        .eq("hidden_for_recipient", false)
        .is("deleted_at", null);
      if (!cancelled) setInboxPending(count || 0);
    };
    load();
    const channel = supabase
      .channel(`dash-inbox-${user.id}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`)
      .on("postgres_changes", {
        event: "*", schema: "public", table: "document_signatures",
        filter: `recipient_user_id=eq.${user.id}`,
      }, () => load())
      .subscribe();
    return () => { cancelled = true; supabase.removeChannel(channel); };
  }, [user?.id]);
  const pendingDocsCount = docsPending + inboxPending;
  const pendingReasons: string[] = [];
  if (docsPending > 0) {
    pendingReasons.push(
      docsPending === 1
        ? "загрузить 1 документ"
        : `загрузить ${docsPending} документ${docsPending < 5 ? "а" : "ов"}`
    );
  }
  if (inboxPending > 0) {
    pendingReasons.push(
      inboxPending === 1
        ? "подписать 1 документ от организации"
        : `подписать ${inboxPending} документ${inboxPending < 5 ? "а" : "ов"} от организации`
    );
  }

  if (userRole && userRole !== 'student' && !isAdminView && !isAdminViewFromStorage && !isPreviewMode && !isPreviewFromStorage) {
    if (userRole === 'organization') return <Navigate to="/organization" replace />;
    if (userRole === 'company') return <Navigate to="/company" replace />;
    if (userRole === 'admin') return <Navigate to="/admin" replace />;
    if (userRole === 'sales_manager') return <Navigate to="/sales" replace />;
  }

  if (loading) return <div className="min-h-screen flex items-center justify-center"><SigmaSpinner size="lg" /></div>;
  if (loadError && !offlineCopy) return <AccountLoadError title="Не удалось загрузить курсы" onRetry={handleRefresh} />;

  const handleCourseClick = async (courseId: string, isEnrolled: boolean) => {
    if (isEnrolled) {
      // An enrolled reviewer may receive an unpublished, library-only course.
      // Resolve that narrow route through the column-limited RPC before any
      // normal course access or video-identification checks. A rejection is
      // expected for ordinary courses whose library feature is disabled.
      try {
        const shell = await fetchCourseLibraryShell(courseId);
        if (shell.libraryOnly) {
          navigate(`/course/${courseId}/learn?view=library`);
          return;
        }
      } catch {
        // Continue through the established published-course flow.
      }

      // Course access is rechecked against the actual enrollment by the learning page.
      // Pending identity evidence never becomes a new learning grant.
      navigate(`/course/${courseId}/learn`);
    } else {
      navigate(`/course/${courseId}/landing`);
    }
  };

  // Bottom navigation items for mobile
  const bottomNavItems: { id: StudentTab; icon: typeof BookOpen; label: string }[] = [
    { id: "catalog", icon: BookOpen, label: "Курсы" },
    ...(!isNativeLearner ? [{ id: "chat" as StudentTab, icon: MessageCircle, label: "Чат" }] : []),
    { id: "profile" as StudentTab, icon: User, label: "Профиль" },
  ];

  return (
    <div className="min-h-screen bg-background flex overflow-x-hidden">

      {/* Admin/preview bar */}
      {isAdminView && (
        <div className="fixed top-0 left-0 right-0 z-50 bg-primary text-primary-foreground py-2 px-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Eye className="w-4 h-4" />
            <span className="text-sm font-medium">Режим просмотра: {adminViewStudentName}</span>
          </div>
          <Button variant="secondary" size="sm" onClick={() => {
            const raw = localStorage.getItem('adminViewAsStudent');
            let returnPath = '/admin';
            try { const d = JSON.parse(raw || '{}'); if (d.orgReturn) returnPath = d.orgReturn; } catch { /* Ignore malformed preview state. */ }
            localStorage.removeItem('adminViewAsStudent');
            navigate(returnPath);
          }} className="gap-1">
            <X className="w-3 h-3" />Выйти
          </Button>
        </div>
      )}
      {isPreviewMode && !isAdminView && !isDemoStudent && (
        <div className="fixed top-0 inset-x-0 bg-primary text-primary-foreground py-2 px-4 text-center text-sm z-50 flex items-center justify-center gap-2">
          <Eye className="w-4 h-4" />Режим предпросмотра
          <Button size="sm" variant="secondary" className="ml-4 h-7" onClick={() => window.close()}>Закрыть</Button>
        </div>
      )}
      {isDemoStudent && !isAdminView && (
        <div className="fixed top-0 left-0 right-0 z-50 bg-primary text-primary-foreground py-2 px-4 flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <Eye className="w-4 h-4" />
            <span className="text-sm font-medium">Демо-кабинет ученика</span>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="secondary" size="sm" className="gap-1" onClick={async () => {
              try {
                const raw = localStorage.getItem('demoStudentReturn');
                const data = raw ? JSON.parse(raw) : null;
                localStorage.removeItem('demoStudentReturn');
                if (data?.access_token && data?.refresh_token) {
                  await supabase.auth.signOut();
                  const { error } = await supabase.auth.setSession({
                    access_token: data.access_token,
                    refresh_token: data.refresh_token,
                  });
                  if (error) throw error;
                  window.location.href = data.returnPath || '/organization';
                } else {
                  navigate('/auth');
                }
              } catch (e) {
                console.error('Return to org failed', e);
                toast.error('Не удалось вернуться. Войдите заново.');
                navigate('/auth');
              }
            }}>← Назад в организацию</Button>
            <Button variant="secondary" size="sm" className="gap-1" onClick={async () => {
              localStorage.removeItem('demoStudentReturn');
              await supabase.auth.signOut();
              navigate('/auth');
            }}>
              <X className="w-3 h-3" />Выйти
            </Button>
          </div>
        </div>
      )}

      {/* Desktop sidebar — hidden on mobile */}
      <div className="hidden md:block">
        <StudentSidebar
          activeTab={currentTab}
          setActiveTab={setActiveTab}
          branding={branding}
          orgName={profile?.organization_name || null}
          showChat={!isNativeLearner}
          isPreviewMode={isPreviewMode}
          isAdminView={isAdminView}
        />
      </div>

      {/* Main content */}
      <div className={cn("flex-1 flex flex-col min-w-0", (isPreviewMode || isAdminView || isDemoStudent) && "md:mt-10")}>
        {/* Top header */}
        <StudentHeader
          fullName={profile?.full_name || null}
          orgName={profile?.organization_name || null}
          logoUrl={branding?.logoUrl}
          onLogout={handleLogout}
          setTheme={setTheme}
          pendingCount={pendingDocsCount}
          pendingReasons={pendingReasons}
          isVideoIdentified={isVideoIdentified}
          showAchievements={!isNativeLearner && dashboardSettings.showAchievements}
          showRadio={!isNativeLearner && dashboardSettings.showRadio}
          showAnnouncements={dashboardSettings.showAnnouncements}
          showDrivingSchool={showDrivingSchool}

          onShowVideoId={() => setShowVideoIdentification(true)}
          onShowConsent={() => setShowConsentForm(true)}
          onShowDocs={() => setShowDocumentsUpload(true)}
          onShowAchievements={() => setShowAchievements(true)}
          onProfileClick={() => setActiveTab("profile" as any)}
        />

        <main
          ref={isMobile ? pullToRefreshRef : undefined}
          className="flex-1 overflow-y-auto overflow-x-hidden md:pt-0 flex flex-col pb-20 md:pb-0 w-full max-w-full"
        >
          {isMobile && <PullToRefreshIndicator pullDistance={pullDistance} isRefreshing={isRefreshing} canRefresh={canRefresh} threshold={80} />}

          {loadError && offlineCopy && <div role="status" className="m-4 md:m-6 rounded-lg border bg-muted/40 p-4 flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-medium">Показана сохранённая копия кабинета</p><p className="text-sm text-muted-foreground">Сейчас не удалось подтвердить обновления. Данные могут быть устаревшими.</p></div><Button variant="outline" onClick={() => void handleRefresh()}>Повторить загрузку</Button></div>}

          {(currentTab === "catalog" || currentTab === "chat") && (
            <div className="p-4 md:p-6 space-y-4 md:space-y-6 max-w-[1400px] mx-auto w-full flex-1">
              <OrgBanner
                orgName={profile?.organization_name || null}
                orgDescription={profile?.org_description}
                coverUrl={branding?.coverUrl}
                coverPosition={branding?.coverPosition}
                logoUrl={branding?.logoUrl}
                primaryColor={branding?.primaryColor}
                secondaryColor={branding?.secondaryColor}
                totalProgress={totalProgress}
                totalTimeSpent={totalTimeSpent}
                totalCompletedLessons={totalCompletedLessons}
                enrolledCount={courses.length}
                formatTime={formatTime}
              />

              {currentTab === "catalog" && !!user?.id && !isAdminView && !isPreviewMode && !isAdminViewFromStorage && effectiveStudentId === user?.id && profile?.organization_id && <RetainedResultsButton
                organizationId={profile.organization_id} userId={user.id} courseLabels={Object.fromEntries(courses.map(course => [course.id, course.title]))} />}
              {currentTab === "catalog" && (
                <CatalogContent
                  catalogCourses={isNativeLearner || dashboardSettings.catalogMode === "assigned" ? [] : catalogCourses}
                  categories={categories}
                  handleCourseClick={handleCourseClick}
                  enrolledCourses={courses}
                  isVideoIdentified={isVideoIdentified}
                  totalProgress={totalProgress}
                  totalTimeSpent={totalTimeSpent}
                  totalCompletedLessons={totalCompletedLessons}
                  formatTime={formatTime}
                  user={user}
                  contentTab="courses"
                  isAdminView={isAdminView}
                />
              )}

              {!isNativeLearner && currentTab === "chat" && (
                <StudentChatsTab
                  showAiChat={dashboardSettings.showAiChat}
                  organizationId={profile?.organization_id}
                  organizationName={profile?.organization_name || "Организация"}
                />
              )}
            </div>
          )}

          {/* Profile tab */}
          {currentTab === ("profile" as any) && effectiveStudentId && (
            <div className="flex-1">
              <StudentProfileContent
                effectiveUserId={effectiveStudentId}
                isAdminView={isAdminView}
                pendingDocsCount={pendingDocsCount}
              />
            </div>
          )}

          {/* Footer */}
          {(currentTab === "catalog" || currentTab === ("profile" as any)) && (
            <StudentFooter
              orgName={profile?.organization_name || null}
              logoUrl={branding?.logoUrl}
              orgDescription={profile?.org_description}
            />
          )}
        </main>
      </div>

      {/* Mobile bottom navigation */}
      <div className="md:hidden fixed bottom-0 inset-x-0 z-40 bg-card border-t border-border">
        <nav className="flex items-center justify-around h-14">
          {bottomNavItems.map(item => {
            const isActive = currentTab === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={cn(
                  "flex flex-col items-center justify-center gap-0.5 flex-1 h-full transition-colors",
                  isActive ? "text-primary" : "text-muted-foreground"
                )}
              >
                <item.icon className="w-5 h-5" />
                <span className="text-[10px] font-medium">{item.label}</span>
              </button>
            );
          })}
        </nav>
      </div>

      {/* Dialogs */}
      {showVideoIdentification && effectiveStudentId && (
        <VideoIdentification
          userId={effectiveStudentId}
          userName={effectiveStudentName}
          organizationId={profile?.organization_id || undefined}
          isOpen={showVideoIdentification}
          onOpenChange={setShowVideoIdentification}
          onSubmitted={() => { void handleRefresh(); }}
        />
      )}
      {showConsentForm && effectiveStudentId && (
        <StudentConsentForm
          userId={effectiveStudentId}
          userName={effectiveStudentName}
          organizationId={profile?.organization_id || ""}
          isOpen={showConsentForm}
          onOpenChange={setShowConsentForm}
        />
      )}
      {showDocumentsUpload && effectiveStudentId && (
        <StudentDocumentsUpload
          userId={effectiveStudentId}
          organizationId={profile?.organization_id || ""}
          isOpen={showDocumentsUpload}
          onOpenChange={setShowDocumentsUpload}
          requiredTypes={documentsProgress.requiredTypes}
        />
      )}
      {!isNativeLearner && showAchievements && user && (
        <AchievementsPanel
          userId={user.id}
          isOpen={showAchievements}
          onOpenChange={setShowAchievements}
        />
      )}
      {showOnboarding && <OnboardingDialog open={showOnboarding} onClose={handleOnboardingClose} steps={studentOnboardingSteps} />}
    </div>
  );
}

import { act, renderHook, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createClient } from '@supabase/supabase-js';
import { deferred } from './fixtures';
const ports = vi.hoisted(() => ({
  auth: { user: { id: 'qa-user-A' } as { id: string } | null, loading: false, authError: null as string | null, userRole: 'student' },
  rpc: vi.fn(), signals: [] as AbortSignal[],
}));
vi.mock('@/hooks/useAuth', () => ({ useAuth: () => ports.auth }));
vi.mock('@/integrations/supabase/client', () => ({ supabase: {
  rpc: (...args: unknown[]) => {
    const request = ports.rpc(...args);
    if (request && typeof request.abortSignal === 'function') return request;
    return { abortSignal: (signal: AbortSignal) => {
      ports.signals.push(signal);
      return Promise.resolve(request).then(data => ({ data, error: null }));
    } };
  },
} }));
import { useDrivingSchoolParticipantEntry } from '@/hooks/useDrivingSchoolParticipantEntry';

type Scope = { org: string | null; subject: string | null; enabled: boolean };
const initial: Scope = { org: 'qa-org-A', subject: 'qa-user-A', enabled: true };
const student = (org = 'qa-org-A') => ({ organization_id: org, name: 'QA School', role: 'student' });
const instructor = (org = 'qa-org-A') => ({ organization_id: org, name: 'QA School', role: 'instructor' });
function useEntry(value: Scope) {
  return useDrivingSchoolParticipantEntry(value.org, value.subject, value.enabled);
}
beforeEach(() => {
  ports.auth = { user: { id: 'qa-user-A' }, loading: false, authError: null, userRole: 'student' };
  ports.signals = [];
  ports.rpc.mockReset().mockImplementation(() => { throw new Error('Unexpected participant lookup'); });
  vi.spyOn(document, 'visibilityState', 'get').mockReturnValue('visible');
});
afterEach(() => { vi.useRealTimers(); });

describe('ordinary account participant entry visibility', () => {
  it('ASPE01 absent Auth, pending Auth, Auth error, absent organization, absent subject, identity mismatch and disabled preview never call the RPC', () => {
    const cases: Array<{ auth: typeof ports.auth; scope: Scope }> = [
      { auth: { ...ports.auth, user: null }, scope: initial },
      { auth: { ...ports.auth, loading: true }, scope: initial },
      { auth: { ...ports.auth, authError: 'SESSION_UNAVAILABLE' }, scope: initial },
      { auth: ports.auth, scope: { ...initial, org: null } },
      { auth: ports.auth, scope: { ...initial, subject: null } },
      { auth: ports.auth, scope: { ...initial, subject: 'different-user' } },
      { auth: ports.auth, scope: { ...initial, enabled: false } },
    ];
    for (const value of cases) {
      ports.auth = value.auth;
      const view = renderHook(() => useEntry(value.scope));
      expect(view.result.current).toBe(false);
      view.unmount();
    }
    expect(ports.rpc).not.toHaveBeenCalled();
  });

  it('ASPE02 pending lookup is hidden and an exact server-confirmed student in the current organization opens the entry', async () => {
    const pending = deferred<unknown>();
    ports.rpc.mockReturnValueOnce(pending.promise);
    const view = renderHook(() => useEntry(initial));
    expect(view.result.current).toBe(false);
    expect(ports.rpc).toHaveBeenCalledExactlyOnceWith('driving_my_schools');
    await act(async () => pending.resolve([student()]));
    expect(view.result.current).toBe(true);
  });

  it('ASPE03 an ordinary account bound as instructor is eligible without any management capability or inferred account role', async () => {
    ports.rpc.mockResolvedValueOnce([instructor()]);
    const view = renderHook(() => useEntry(initial));
    await waitFor(() => expect(view.result.current).toBe(true));
    expect(ports.auth.userRole).toBe('student');
    expect(ports.rpc).toHaveBeenCalledExactlyOnceWith('driving_my_schools');
  });

  it('ASPE04 empty server selection for an unbound or disconnected account remains hidden without inventing a connected flag', async () => {
    ports.rpc.mockResolvedValueOnce([]);
    const view = renderHook(() => useEntry(initial));
    await waitFor(() => expect(ports.rpc).toHaveBeenCalledTimes(1));
    expect(view.result.current).toBe(false);
    await act(async () => { await Promise.resolve(); });
    expect(view.result.current).toBe(false);
  });

  it('ASPE05 wrong organizations and malformed, missing or unsupported server rows never open the entry', async () => {
    const values: unknown[] = [
      [student('qa-other-org')], null, {}, 'qa-school',
      [null], [{ organization_id: 'qa-org-A', name: 'QA', role: 'owner' }],
      [{ organization_id: 'qa-org-A', role: 'student' }],
      [{ organization_id: '', name: 'QA', role: 'student' }],
      [student(), { organization_id: 'qa-other-org', name: 7, role: 'instructor' }],
    ];
    for (const value of values) {
      ports.rpc.mockResolvedValueOnce(value);
      const view = renderHook(() => useEntry(initial));
      await act(async () => { await Promise.resolve(); });
      expect(view.result.current).toBe(false);
      view.unmount();
    }
    expect(ports.rpc).toHaveBeenCalledTimes(values.length);
  });

  it('ASPE06 multiple valid school rows are checked for the actual organization and do not imply selecting a first school', async () => {
    ports.rpc.mockResolvedValueOnce([student('qa-other-org'), instructor('qa-org-A')]);
    const view = renderHook(() => useEntry(initial));
    await waitFor(() => expect(view.result.current).toBe(true));
    expect(ports.rpc).toHaveBeenCalledExactlyOnceWith('driving_my_schools');
  });

  it('ASPE07 a fresh focus check hides the previous success while pending and keeps it closed after a permission or network failure', async () => {
    const pending = deferred<unknown>();
    ports.rpc.mockResolvedValueOnce([student()]).mockReturnValueOnce(pending.promise);
    const view = renderHook(() => useEntry(initial));
    await waitFor(() => expect(view.result.current).toBe(true));
    act(() => window.dispatchEvent(new Event('focus')));
    expect(view.result.current).toBe(false);
    await act(async () => pending.reject(new Error('DRIVING_FORBIDDEN')));
    expect(view.result.current).toBe(false);
  });

  it('ASPE08 repeated focus and visibility events do not accumulate overlapping RPCs while a lookup is pending', async () => {
    const pending = deferred<unknown>();
    ports.rpc.mockReturnValueOnce(pending.promise);
    const view = renderHook(() => useEntry(initial));
    act(() => {
      window.dispatchEvent(new Event('focus'));
      document.dispatchEvent(new Event('visibilitychange'));
      window.dispatchEvent(new Event('focus'));
    });
    expect(ports.rpc).toHaveBeenCalledTimes(1);
    expect(view.result.current).toBe(false);
    await act(async () => pending.resolve([student()]));
    expect(view.result.current).toBe(true);
    ports.rpc.mockResolvedValueOnce([]);
    await act(async () => { window.dispatchEvent(new Event('focus')); await Promise.resolve(); });
    expect(view.result.current).toBe(false);
    expect(ports.rpc).toHaveBeenCalledTimes(2);
  });

  it('ASPE09 a new account checks independently while the predecessor read never completes and its physical signal is aborted', async () => {
    const oldPending = deferred<unknown>(), nextPending = deferred<unknown>();
    ports.rpc.mockResolvedValueOnce([student()]).mockReturnValueOnce(oldPending.promise).mockReturnValueOnce(nextPending.promise);
    const view = renderHook(useEntry, { initialProps: initial });
    await waitFor(() => expect(view.result.current).toBe(true));
    act(() => window.dispatchEvent(new Event('focus')));
    ports.auth = { ...ports.auth, user: { id: 'qa-user-B' } };
    view.rerender({ ...initial, subject: 'qa-user-B' });
    expect(view.result.current).toBe(false);
    expect(ports.signals[1].aborted).toBe(true);
    expect(ports.rpc).toHaveBeenCalledTimes(3);
    await act(async () => nextPending.resolve([instructor()]));
    expect(view.result.current).toBe(true);
    await act(async () => oldPending.resolve([]));
    expect(view.result.current).toBe(true);
  });

  it('ASPE10 returning from account A through B to A aborts both predecessors and never accepts an older A response', async () => {
    const firstA = deferred<unknown>(), pendingB = deferred<unknown>(), newA = deferred<unknown>();
    ports.rpc.mockReturnValueOnce(firstA.promise).mockReturnValueOnce(pendingB.promise).mockReturnValueOnce(newA.promise);
    const view = renderHook(useEntry, { initialProps: initial });
    ports.auth = { ...ports.auth, user: { id: 'qa-user-B' } };
    view.rerender({ ...initial, subject: 'qa-user-B' });
    ports.auth = { ...ports.auth, user: { id: 'qa-user-A' } };
    view.rerender(initial);
    expect(ports.rpc).toHaveBeenCalledTimes(3);
    expect(ports.signals[0].aborted).toBe(true);
    expect(ports.signals[1].aborted).toBe(true);
    await act(async () => firstA.resolve([student()]));
    expect(view.result.current).toBe(false);
    await act(async () => pendingB.resolve([student()]));
    expect(view.result.current).toBe(false);
    await act(async () => newA.resolve([student()]));
    expect(view.result.current).toBe(true);
  });

  it('ASPE11 a new organization checks without waiting for a hung old organization and cannot inherit its response', async () => {
    const older = deferred<unknown>(), newer = deferred<unknown>();
    ports.rpc.mockReturnValueOnce(older.promise).mockReturnValueOnce(newer.promise);
    const view = renderHook(useEntry, { initialProps: initial });
    view.rerender({ ...initial, org: 'qa-org-B' });
    expect(ports.signals[0].aborted).toBe(true);
    expect(ports.rpc).toHaveBeenCalledTimes(2);
    await act(async () => newer.resolve([student('qa-org-B')]));
    expect(view.result.current).toBe(true);
    await act(async () => older.resolve([]));
    expect(view.result.current).toBe(true);
  });

  it('ASPE12 disabling and unmounting dispose pending requests and remove focus and visibility listeners', async () => {
    const disabledPending = deferred<unknown>(), unmountedPending = deferred<unknown>();
    ports.rpc.mockReturnValueOnce(disabledPending.promise).mockReturnValueOnce(unmountedPending.promise);
    const view = renderHook(useEntry, { initialProps: initial });
    view.rerender({ ...initial, enabled: false });
    expect(ports.signals[0].aborted).toBe(true);
    await act(async () => disabledPending.resolve([student()]));
    expect(view.result.current).toBe(false);
    view.rerender(initial);
    expect(ports.rpc).toHaveBeenCalledTimes(2);
    view.unmount();
    expect(ports.signals[1].aborted).toBe(true);
    await act(async () => unmountedPending.resolve([student()]));
    act(() => {
      window.dispatchEvent(new Event('focus'));
      document.dispatchEvent(new Event('visibilitychange'));
    });
    expect(ports.rpc).toHaveBeenCalledTimes(2);
  });

  it('ASPE13 visibility and focus rechecks are event-driven, stay quiet while hidden and close a revoked server selection', async () => {
    ports.rpc.mockResolvedValueOnce([student()]);
    const view = renderHook(() => useEntry(initial));
    await waitFor(() => expect(view.result.current).toBe(true));
    const visibility = vi.spyOn(document, 'visibilityState', 'get').mockReturnValue('hidden');
    act(() => {
      window.dispatchEvent(new Event('focus'));
      document.dispatchEvent(new Event('visibilitychange'));
    });
    expect(ports.rpc).toHaveBeenCalledTimes(1);
    visibility.mockReturnValue('visible');
    ports.rpc.mockResolvedValueOnce([]);
    await act(async () => { document.dispatchEvent(new Event('visibilitychange')); await Promise.resolve(); });
    expect(view.result.current).toBe(false);
    expect(ports.rpc).toHaveBeenCalledTimes(2);
    ports.rpc.mockResolvedValueOnce([instructor()]);
    await act(async () => { window.dispatchEvent(new Event('focus')); await Promise.resolve(); });
    expect(view.result.current).toBe(true);
    expect(ports.rpc).toHaveBeenCalledTimes(3);
  });

  it('ASPE14 a returned RPC error cannot open the entry even if the envelope also contains apparently valid data', async () => {
    ports.rpc.mockReturnValueOnce({ abortSignal: () => Promise.resolve({ data: [student()], error: { code: '42501' } }) });
    const view = renderHook(() => useEntry(initial));
    await act(async () => { await Promise.resolve(); });
    expect(view.result.current).toBe(false);
    expect(ports.rpc).toHaveBeenCalledExactlyOnceWith('driving_my_schools');
  });

  it('ASPE15 the actual installed Supabase query builder forwards a physical abort signal and bounded timeout never accumulates live fetches', async () => {
    vi.useFakeTimers({ toFake: ['setTimeout', 'clearTimeout'] });
    const signals: AbortSignal[] = [];
    const paths: string[] = [];
    let active = 0, maximumActive = 0;
    const transport = vi.fn((input: RequestInfo | URL, init?: RequestInit) => new Promise<Response>((_resolve, reject) => {
      const signal = init?.signal;
      if (!signal) throw new Error('Actual SDK failed to forward the abort signal');
      expect(typeof input).toBe('string');
      paths.push(new URL(String(input)).pathname);
      signals.push(signal);
      if (signal.aborted) { reject(new DOMException('Aborted', 'AbortError')); return; }
      active++; maximumActive = Math.max(maximumActive, active);
      signal.addEventListener('abort', () => {
        active--; reject(new DOMException('Aborted', 'AbortError'));
      }, { once: true });
    }));
    const client = createClient('https://qa.example.invalid', 'synthetic-publishable-key', {
      auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false },
      global: { fetch: transport as typeof fetch },
    });
    ports.rpc.mockImplementation((name: string) => client.rpc(name));
    let view!: ReturnType<typeof renderHook<boolean, Scope>>;
    await act(async () => {
      view = renderHook(useEntry, { initialProps: initial });
      for (let i = 0; i < 30; i++) await Promise.resolve();
    });
    expect(transport).toHaveBeenCalledTimes(1);
    expect(paths).toEqual(['/rest/v1/rpc/driving_my_schools']);
    expect(view.result.current).toBe(false);
    await act(async () => {
      vi.advanceTimersByTime(12000);
      for (let i = 0; i < 30; i++) await Promise.resolve();
    });
    expect(signals[0].aborted).toBe(true);
    expect(active).toBe(0);
    expect(view.result.current).toBe(false);
    await act(async () => {
      window.dispatchEvent(new Event('focus'));
      for (let i = 0; i < 30; i++) await Promise.resolve();
    });
    expect(transport).toHaveBeenCalledTimes(2);
    expect(signals[1].aborted).toBe(false);
    expect(maximumActive).toBe(1);
    view.unmount();
    expect(signals[1].aborted).toBe(true);
    expect(active).toBe(0);
    await act(async () => { for (let i = 0; i < 30; i++) await Promise.resolve(); });
  });

});

